import unittest

def has_quorum_fixed(acks, voters):
    required = len(voters) // 2 + 1
    return len(set(acks) & voters) >= required

class LearnerPromotionTests(unittest.TestCase):
    def test_learner_does_not_increase_voting_threshold(self):
        voters = {'a', 'b', 'c'}
        learners = {'d'}
        acknowledgements = {'a', 'b'}
        self.assertFalse(has_quorum(acknowledgements, voters, learners))
        self.assertTrue(has_quorum_fixed(acknowledgements, voters))

    def test_learner_acknowledgement_cannot_replace_a_voter(self):
        voters = {'a', 'b', 'c'}
        learners = {'d'}
        acknowledgements = {'a', 'b', 'd'}
        self.assertTrue(has_quorum(acknowledgements, voters, learners))
        self.assertFalse(has_quorum_fixed(acknowledgements, voters))
